create extension if not exists pgcrypto;
create table if not exists public.assets(id uuid primary key default gen_random_uuid(),name text not null,symbol text not null unique,logo_url text,price_usd numeric(30,12) not null default 0,circulating_supply numeric(40,12) not null default 0,is_custom boolean not null default false,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.wallets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,currency text not null,balance numeric(40,18) not null default 0,updated_at timestamptz not null default now(),unique(user_id,currency));
create table if not exists public.ledger_entries(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),currency text not null,amount numeric(40,18) not null,entry_type text not null,reference_id uuid,reason text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),symbol text not null,side text not null,amount_usd numeric(30,12) not null,fee_usd numeric(30,12) not null,price_usd numeric(30,12) not null,status text not null default 'filled',created_at timestamptz not null default now());
create table if not exists public.deposit_networks(id uuid primary key default gen_random_uuid(),asset_symbol text not null,network_name text not null,deposit_address text not null,qr_image_url text,enabled boolean not null default true,updated_at timestamptz not null default now(),unique(asset_symbol,network_name));
create table if not exists public.deposit_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),asset_symbol text not null,network_name text not null,amount numeric(40,18) not null,proof_image_url text,status text not null default 'pending',created_at timestamptz not null default now());
create table if not exists public.withdraw_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),asset_symbol text not null,network_name text not null,amount numeric(40,18) not null,receiving_qr_url text,wallet_address text not null,status text not null default 'pending',created_at timestamptz not null default now());
-- Production: enable RLS on all tables and expose mutations only through authenticated server-side functions.
